const webhookData = $('Webhook prepliego-general').item.json.body;
const empresas = $('Postgres - Obtener empresas').all().map(e => e.json);
const documentosBase64 = webhookData.documentosBase64 || [];
const licitacion = webhookData.licitacion || {};

const systemPrompt = 'Eres un experto juridico en contratacion publica colombiana (SECOP II). Analiza el borrador del pliego / estudio previo adjunto y devuelve UNICAMENTE un JSON valido (sin markdown) con la siguiente estructura exacta: {"resumen_ejecutivo":"string","requisitos_habilitantes":{"juridico":["string"],"financiero":["string"],"tecnico":["string"],"experiencia":["string"]},"criterios_ponderacion":[{"criterio":"string","peso":0}],"fechas_clave":[{"fecha":"string","evento":"string"}],"cascaritas":[{"descripcion":"string","ubicacion":"string"}],"empresas_candidatas":[{"empresa_id":"string","nombre_empresa":"string","afinidad_resumen":"string"}]}';

const empresasTexto = empresas.length > 0
  ? empresas.map(e => {
      const perfil = e.contexto_procesado ? JSON.stringify(e.contexto_procesado) : 'Sin perfil';
      return 'ID: ' + e.id + ' | ' + e.nombre + ' | ' + (e.sector || 'N/A') + '\n' + perfil;
    }).join('\n---\n')
  : 'Sin empresas disponibles.';

const userText = 'Licitacion: ' + (licitacion.nombre || '') + (licitacion.secop_id ? ' (SECOP: ' + licitacion.secop_id + ')' : '') + '\n\nEMPRESAS DISPONIBLES (candidatas al pre-pliego):\n' + empresasTexto + '\n\nA continuacion se adjuntan los documentos del pre-pliego.';

const contentBlocks = [{ type: 'text', text: userText }];
for (const doc of documentosBase64) {
  contentBlocks.push({
    type: 'document',
    source: { type: 'base64', media_type: doc.mediaType, data: doc.base64 },
    title: doc.nombre
  });
}
if (documentosBase64.length === 0) {
  contentBlocks.push({ type: 'text', text: 'Nota: No se adjuntaron documentos.' });
}

const requestBody = {
  model: 'claude-sonnet-4-6',
  max_tokens: 4096,
  system: systemPrompt,
  messages: [{ role: 'user', content: contentBlocks }]
};

return [{ json: { faseId: webhookData.faseId, claudeBody: JSON.stringify(requestBody) } }];

const response = $('Claude API - Analisis general').item.json;
const buildData = $('Code - Build Claude Request').item.json;

let rawText = '';
if (response.content && response.content[0] && response.content[0].text) {
  rawText = response.content[0].text.trim().replace(/```json/g, '').replace(/```/g, '').trim();
}

let parsed = null;
try {
  parsed = JSON.parse(rawText);
} catch(e) {
  parsed = { error: 'respuesta_no_valida', raw: rawText.substring(0, 500) };
}

return [{ json: { faseId: buildData.faseId, resultado: JSON.stringify(parsed) } }];
